// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title DistributedCacheClient
/// @notice A distributed cache with audit logging and web dashboard integration
contract DistributedCacheClient {
    struct CacheEntry {
        bytes value;
        uint256 timestamp;
        address setter;
        string metadata;
    }

    struct AuditLog {
        address actor;
        string action;
        string key;
        string details;
        uint256 timestamp;
    }

    mapping(string => CacheEntry) private cache;
    AuditLog[] public auditLogs;
    mapping(address => bool) public authorized;
    address public owner;

    // Dashboard rendering configuration
    string private dashboardTemplate;
    bool public htmlRenderingEnabled;

    event CacheSet(string indexed key, address indexed setter);
    event CacheInvalidated(string indexed key, address indexed actor);
    event AuditLogCreated(uint256 indexed logIndex, string action);

    modifier onlyAuthorized() {
        require(authorized[msg.sender] || msg.sender == owner, "Unauthorized");
        _;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
        authorized[msg.sender] = true;
        htmlRenderingEnabled = true;
        dashboardTemplate = "<div class='cache-dashboard'>";
    }

    function authorize(address user) external onlyOwner {
        authorized[user] = true;
    }

    function revoke(address user) external onlyOwner {
        authorized[user] = false;
    }

    function setCache(string calldata key, bytes calldata value, string calldata metadata) external onlyAuthorized {
        cache[key] = CacheEntry({
            value: value,
            timestamp: block.timestamp,
            setter: msg.sender,
            metadata: metadata
        });

        _createAuditLog("SET", key, metadata);
        emit CacheSet(key, msg.sender);
    }

    function getCache(string calldata key) external view returns (bytes memory, uint256, address) {
        CacheEntry storage entry = cache[key];
        return (entry.value, entry.timestamp, entry.setter);
    }

    function invalidateCache(string calldata key) external onlyAuthorized {
        delete cache[key];
        _createAuditLog("INVALIDATE", key, "");
        emit CacheInvalidated(key, msg.sender);
    }

    function _createAuditLog(string memory action, string memory key, string memory details) internal {
        auditLogs.push(AuditLog({
            actor: msg.sender,
            action: action,
            key: key,
            details: details,
            timestamp: block.timestamp
        }));
        emit AuditLogCreated(auditLogs.length - 1, action);
    }

    /// @notice Renders audit log as HTML fragment for the web dashboard
    /// @dev The dashboard frontend calls this via eth_call to render logs
    /// @param startIndex Starting index in audit log array
    /// @param count Number of entries to render
    function renderAuditLogHTML(uint256 startIndex, uint256 count) external view returns (string memory) {
        require(htmlRenderingEnabled, "HTML rendering disabled");
        require(startIndex + count <= auditLogs.length, "Out of bounds");

        string memory html = dashboardTemplate;

        for (uint256 i = startIndex; i < startIndex + count; i++) {
            AuditLog storage log = auditLogs[i];

            // Build HTML row for each audit entry
            html = string(abi.encodePacked(
                html,
                "<tr><td>",
                _addressToString(log.actor),
                "</td><td>",
                log.action,
                "</td><td class='cache-key'>",
                _htmlEncode(log.key),
                "</td><td class='details'>",
                _renderDetails(log.details),
                "</td><td>",
                _uint256ToString(log.timestamp),
                "</td></tr>"
            ));
        }

        html = string(abi.encodePacked(html, "</div>"));
        return html;
    }

    /// @notice Renders detail field with consistent encoding
    /// @dev All content is HTML-encoded regardless of prefix markers
    function _renderDetails(string memory details) internal pure returns (string memory) {
        bytes memory detailBytes = bytes(details);

        if (detailBytes.length == 0) {
            return "<em>none</em>";
        }

        // Check for rich content prefix - strip it but still encode
        // This maintains backward compatibility with clients sending html: prefix
        // while ensuring all output is safely encoded
        if (detailBytes.length > 5) {
            bytes memory prefix = new bytes(5);
            for (uint256 i = 0; i < 5; i++) {
                prefix[i] = detailBytes[i];
            }
            if (keccak256(prefix) == keccak256(bytes("html:"))) {
                // Strip prefix but still encode the content safely
                bytes memory content = new bytes(detailBytes.length - 5);
                for (uint256 i = 5; i < detailBytes.length; i++) {
                    content[i - 5] = detailBytes[i];
                }
                return _htmlEncode(string(content));
            }
        }

        // Apply entity encoding for safety
        return _htmlEncode(details);
    }

    function _htmlEncode(string memory input) internal pure returns (string memory) {
        bytes memory inputBytes = bytes(input);
        // Estimate output size (worst case 6x for &#xx; encoding)
        bytes memory output = new bytes(inputBytes.length * 6);
        uint256 outputLen = 0;

        for (uint256 i = 0; i < inputBytes.length; i++) {
            bytes1 char = inputBytes[i];
            if (char == '<') {
                output[outputLen++] = '&';
                output[outputLen++] = 'l';
                output[outputLen++] = 't';
                output[outputLen++] = ';';
            } else if (char == '>') {
                output[outputLen++] = '&';
                output[outputLen++] = 'g';
                output[outputLen++] = 't';
                output[outputLen++] = ';';
            } else if (char == '&') {
                output[outputLen++] = '&';
                output[outputLen++] = 'a';
                output[outputLen++] = 'm';
                output[outputLen++] = 'p';
                output[outputLen++] = ';';
            } else if (char == '"') {
                output[outputLen++] = '&';
                output[outputLen++] = 'q';
                output[outputLen++] = 'u';
                output[outputLen++] = 'o';
                output[outputLen++] = 't';
                output[outputLen++] = ';';
            } else if (char == "'") {
                output[outputLen++] = '&';
                output[outputLen++] = '#';
                output[outputLen++] = '3';
                output[outputLen++] = '9';
                output[outputLen++] = ';';
            } else {
                output[outputLen++] = char;
            }
        }

        // Trim to actual length
        bytes memory trimmed = new bytes(outputLen);
        for (uint256 i = 0; i < outputLen; i++) {
            trimmed[i] = output[i];
        }
        return string(trimmed);
    }

    function _addressToString(address addr) internal pure returns (string memory) {
        bytes memory alphabet = "0123456789abcdef";
        bytes memory result = new bytes(42);
        result[0] = '0';
        result[1] = 'x';
        for (uint256 i = 0; i < 20; i++) {
            result[2 + i * 2] = alphabet[uint8(uint160(addr) >> (8 * (19 - i)) >> 4) & 0x0f];
            result[3 + i * 2] = alphabet[uint8(uint160(addr) >> (8 * (19 - i))) & 0x0f];
        }
        return string(result);
    }

    function _uint256ToString(uint256 value) internal pure returns (string memory) {
        if (value == 0) return "0";
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }

    function getAuditLogCount() external view returns (uint256) {
        return auditLogs.length;
    }

    function setHtmlRendering(bool enabled) external onlyOwner {
        htmlRenderingEnabled = enabled;
    }
}
